// OnUpdateRange registers the implementation of "update_range".
func OnUpdateRange(h plugin.Host, fn func(plugin.Ctx, *UpdateRangeIn) (*UpdateRangeOut, error)) {
	h.Register(UpdateRangeOperation(), func(ctx plugin.Ctx, raw json.RawMessage, out plugin.Sink) error {
		var in UpdateRangeIn
		if err := contract.BindInput(raw, &in); err != nil {
			return err
		}
		res, err := fn(ctx, &in)
		if err != nil {
			return err
		}
		if res != nil {
			out.Vars(res)
		}
		return nil
	})
}
